use aes::{
    cipher::{BlockCipherEncrypt, KeyInit},
    Aes128,
};
use zeroize::Zeroizing;
#[path = "/Users/pta/Dev/rust/seams-wallet/.worktrees/ml-dsa/crates/ed25519-yao/src/passive/gate_aes.rs"]
mod gate_aes;
#[no_mangle]
pub extern "C" fn measure(mode: u32, rounds: u32, mut seed: u32) -> u32 {
    let key = [19u8; 16];
    let reference = Aes128::new(&key.into());
    let candidate = gate_aes::FourBlockAes128::new(&key);
    let mut checksum = 0u32;
    for round in 0..rounds {
        let mut input = Zeroizing::new([[0u8; 16]; 8]);
        for (lane, block) in input.iter_mut().enumerate() {
            for word in block.chunks_mut(4) {
                seed ^= seed << 13;
                seed ^= seed >> 17;
                seed ^= seed << 5;
                word.copy_from_slice(&seed.to_le_bytes());
            }
            core::hint::black_box((round, lane));
        }
        if mode == 0 {
            let mut blocks = Zeroizing::new([aes::cipher::Block::<Aes128>::default(); 8]);
            for (block, value) in blocks.iter_mut().zip(input.iter()) {
                block.copy_from_slice(value);
            }
            reference.encrypt_blocks(&mut blocks[..]);
            for (value, block) in input.iter_mut().zip(blocks.iter()) {
                value.copy_from_slice(block);
            }
        } else {
            for chunk in input.chunks_mut(4) {
                let mut batch = Zeroizing::new(gate_aes::FourBlocks::default());
                batch.0.copy_from_slice(chunk);
                candidate.encrypt_four(&mut batch);
                chunk.copy_from_slice(&batch.0);
            }
        }
        for block in input.iter() {
            checksum = checksum.wrapping_add(u32::from_le_bytes(block[..4].try_into().unwrap()));
        }
    }
    core::hint::black_box(checksum)
}
